    V L_target;
    V L_tile;
    V L_tx;
    V L_ty;
    { V ut1_ = py::as_seq(callm(a_c, SY("point"), Args{L_p})); L_bx = ut1_.idx(0); L_by = ut1_.idx(1); } 
