        L_dx = (pm_simulation::wrap_delta).call(Args{L_bx, L_tx, pvz::getattr(a_b, SY("width"))});
        L_dy = (L_ty - L_by);
        L_distance = V(std::hypot((L_dx).num(), (L_dy).num()));
